module adder_32bit
    (
      input [32:1] A,
      input [32:1] B, 
      output [32:1] S,
      output C32
    );

    wire [16:1] c1;
    wire [16:1] c2;

    cla_16bit cla1 (
        .a(A[16:1]),
          .b(B[16:1]),
          .cin(0),
          .sum(S[16:1]),
          .cout(c1)
    );

    cla_16bit cla2 (
        .a(A[32:17]),
          .b(B[32:17]),
          .cin(c1),
          .sum(S[32:17]),
          .cout(c2)
    );

    assign C32 = c2;
endmodule
